    local function f(id) return 'rbxassetid://' .. id end
    return {
        SkyboxBk = f(bk), SkyboxDn = f(dn), SkyboxFt = f(ft),
        SkyboxLf = f(lf), SkyboxRt = f(rt), SkyboxUp = f(up),
    }
end

