    if value then
        if not AtmosphereObject then
            AtmosphereObject = Instance.new('Atmosphere')
            AtmosphereObject.Parent = Lighting
        end
        UpdateAtmosphere()
    else
        if AtmosphereObject then
            AtmosphereObject:Destroy()
            AtmosphereObject = nil
        end
    end
end)

